hints:
```
scan edges; if some node v has two parent-edges, record e1 (earlier) and e2 (later)
if no such node:
    for each edge: if union(u,v) fails, return this edge
else:
    for each edge except e2:
        if union(u,v) fails, return e1     # cycle remains without e2
    return e2                              # e2 was the extra edge
```

code.cpp:
class Solution {
    int uf[1001];
public:
    int find(int x) {
        while (uf[x] != x) {
            uf[x] = uf[uf[x]];
            x = uf[x];
        }
        return x;
    }
    bool unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return false;
        uf[rx] = ry;
        return true;
    }
    vector<int> findRedundantDirectedConnection(vector<vector<int>>& edges) {
        int n = edges.size();
        vector<int> par(n + 1, 0);
        int e1 = -1, e2 = -1;
        for (int i = 0; i < n; i++) {
            int v = edges[i][1];
            if (par[v] == 0) {
                par[v] = i + 1;
            } else {
                e1 = par[v] - 1;
                e2 = i;
                break;
            }
        }
        for (int i = 0; i <= n; i++) uf[i] = i;
        if (e1 == -1) {
            for (int i = 0; i < n; i++) {
                if (!unite(edges[i][0], edges[i][1])) {
                    return edges[i];
                }
            }
        } else {
            for (int i = 0; i < n; i++) {
                if (i == e2) continue;
                if (!unite(edges[i][0], edges[i][1])) {
                    return edges[e1];
                }
            }
            return edges[e2];
        }
        return {};
    }
};
